from django.conf.urls import url
from django.shortcuts import render
from django.db import connection

def get_tag_info(request, tag):
    query = "SELECT * FROM tags WHERE name = %s"

    with connection.cursor() as cursor:
        cursor.execute(query, [tag])
        tag_info = cursor.fetchone()

    if tag_info:
        render_tag_template = request.GET.get('t', '')
        render_template = f'{render_tag_template}.html'
        context = {'tag': tag_info}
        return render(request, render_template, context)
    else:
        return Http404()

urlpatterns = [
    url(r'^tag/(?P<tag>\w+)$', get_tag_info),
]
